sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cell;
uniform float angle;
uniform float style;
uniform float colored;
layout(color) uniform half4 ink;
layout(color) uniform half4 paper;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    float a = radians(angle), cs = cos(a), sn = sin(a);
    float s = max(cell, 2);
    if (style > 0.5) {
        float2 q = coord - size * 0.5;
        float2 p = float2(cs * q.x + sn * q.y, -sn * q.x + cs * q.y);
        float j0 = floor(p.y / s + 0.5);
        float near = 1e9;
        float2 hit = float2(0.0);
        for (int k = -1; k <= 1; k++) {
            float j = j0 + float(k);
            float2 m = float2(j * s * 0.5 + floor((p.x - j * s * 0.5) / s + 0.5) * s, j * s);
            float d = distance(p, m);
            if (d < near) { near = d; hit = m; }
        }
        half4 c = unpremul(image.eval(float2(cs * hit.x - sn * hit.y, sn * hit.x + cs * hit.y) + size * 0.5));
        half4 here = image.eval(coord);
        half cover = half(saturate(s * (0.5 - luma(c.rgb)) - near + 0.5));
        half3 rgb = mix(paper.rgb, ink.rgb, cover);
        return half4(rgb * here.a, here.a);
    }
    float2 p = float2(cs * coord.x + sn * coord.y, -sn * coord.x + cs * coord.y);
    float2 m = (floor(p / s) + 0.5) * s;
    half4 c = image.eval(float2(cs * m.x - sn * m.y, sn * m.x + cs * m.y));
    half4 u = unpremul(c);
    float radius = 0.7071 * s * sqrt(max(1 - float(luma(u.rgb)), 0.0));
    half ink2 = half(saturate(radius - distance(p, m) + 0.5));
    half3 rgb = mix(half3(1), colored > 0.5 ? u.rgb : half3(0), ink2);
    return half4(rgb * c.a, c.a);
}
